"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([["5827"],{9294(t){t.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"introducing-busly-cli","metadata":{"permalink":"/busly-cli/blog/introducing-busly-cli","editUrl":"https://github.com/tragiccode/busly-cli/tree/main/docs/blog/2025-12-04-introduction.mdx","source":"@site/blog/2025-12-04-introduction.mdx","title":"Introducing Busly CLI","description":"Working with NServiceBus shouldn\u2019t require spinning up a whole host application just to send a message. That\u2019s why I built Busly CLI \u2014 a lightweight, cross-platform command-line tool that lets you send commands and events instantly. No boilerplate, no fuss, just messaging at your fingertips.","date":"2025-12-04T00:00:00.000Z","tags":[],"readingTime":0.95,"hasTruncateMarker":true,"authors":[{"name":"Michael Fyffe","title":"Creator and Maintainer of busly-cli","url":"https://www.linkedin.com/in/michaelfyffe/","page":{"permalink":"/busly-cli/blog/authors/tragiccode"},"socials":{"linkedin":"https://www.linkedin.com/in/michaelfyffe/","github":"https://github.com/tragiccode","newsletter":"https://www.tragiccode.com"},"imageURL":"https://avatars.githubusercontent.com/u/6224270?v=4","key":"tragiccode"}],"frontMatter":{"slug":"introducing-busly-cli","title":"Introducing Busly CLI","authors":"tragiccode","tags":[]},"unlisted":false},"content":"Working with **NServiceBus** shouldn\u2019t require spinning up a whole host application just to send a message. That\u2019s why I built **Busly CLI** \u2014 a lightweight, cross-platform command-line tool that lets you **send commands and events instantly**. No boilerplate, no fuss, just messaging at your fingertips.\\n\\n{/* truncate */}\\n\\n## Why You\u2019ll Love Busly CLI\\n\\n- \u{1F680} **Send messages straight from your terminal**\\n- \u{1F9E9} **Use custom message types** that match your contracts\\n- \u{1F310} **Works with Azure Service Bus, RabbitMQ, and AWS SQS**\\n- \u2699\uFE0F **Easily switch transports** between local, dev, staging, or production\\n- \u{1F4BB} **Runs on Windows, macOS, and Linux**\\n- \u{1F4E6} **Install your way**: Chocolatey, Docker, .NET tool, or GitHub binary\\n\\n## Help Us Reach 1.0.0\\n\\nBusly CLI is shaping up fast, but I need your help to make **version 1.0.0 rock-solid**:\\n\\n- **Try it out** and let us know what works (or doesn\u2019t).\\n- **Report bugs** on GitHub \u2014 every issue helps!\\n- **Contribute** code, docs, or ideas \u2014 every contribution counts.\\n\\nTogether, we can make **Busly CLI** the go-to tool for messaging in NServiceBus. Jump in, experiment, and help us get to that **stable 1.0.0 release**!\\n\\nCheck it out on [GitHub](https://github.com/tragiccode/busly-cli) and start sending messages in seconds."}]}}')}}]);